const STARTUP_YEARS = [
  "2026", "2025", "2024", "2023", "2022", "2021", "2020", "2019",
  "2018", "2017", "2016", "2015", "2014", "2013", "2012", "2011",
  "2010", "2009", "2008", "2007", "2000–2006", "1987–1999"
];

(() => {
  const archive = document.querySelector("[data-startup-archive]");
  if (!archive) return;

  const yearList = archive.querySelector("[data-startup-years]");
  const grid = archive.querySelector("[data-startup-grid]");
  const count = archive.querySelector("[data-startup-count]");
  const years = STARTUP_YEARS.filter((year) => STARTUPS_BY_YEAR[year]);
  let activeYear = years[0];
  let openCard = null;

  const makeLogoFallback = (name) => {
    const fallback = document.createElement("span");
    fallback.className = "startup-logo-fallback";
    fallback.textContent = name;
    return fallback;
  };

  const closeOpenCard = () => {
    if (!openCard) return;
    openCard.classList.remove("is-open");
    openCard.setAttribute("aria-expanded", "false");
    openCard = null;
  };

  const renderCards = (year) => {
    const startups = STARTUPS_BY_YEAR[year] || [];
    const fragment = document.createDocumentFragment();

    closeOpenCard();
    grid.replaceChildren();
    grid.setAttribute("aria-label", "Start-ups aus " + year);
    count.textContent = startups.length + (startups.length === 1 ? " Start-up" : " Start-ups") + " im Jahr " + year;

    startups.forEach((startup, index) => {
      const item = document.createElement("div");
      item.className = "startup-gallery-item";
      item.setAttribute("role", "listitem");

      const card = document.createElement("button");
      const descriptionId = "startup-description-" + year.replace(/\D/g, "-") + "-" + index;
      card.className = "startup-card";
      card.type = "button";
      card.setAttribute("aria-expanded", "false");
      card.setAttribute("aria-describedby", descriptionId);

      const logoArea = document.createElement("span");
      logoArea.className = "startup-logo-area";
      const fallback = makeLogoFallback(startup.name);

      if (startup.image) {
        const image = document.createElement("img");
        image.src = startup.image;
        image.alt = "";
        image.loading = "lazy";
        image.decoding = "async";
        image.referrerPolicy = "no-referrer";
        fallback.hidden = true;
        image.addEventListener("error", () => {
          image.remove();
          fallback.hidden = false;
        });
        logoArea.append(image, fallback);
      } else {
        logoArea.append(fallback);
      }

      const footer = document.createElement("span");
      footer.className = "startup-card-footer";

      const name = document.createElement("strong");
      name.className = "startup-card-name";
      name.textContent = startup.name;

      const cue = document.createElement("span");
      cue.className = "startup-card-cue";
      cue.textContent = "Kurzprofil +";

      footer.append(name, cue);

      const detail = document.createElement("span");
      detail.className = "startup-card-detail";
      detail.id = descriptionId;

      const detailLabel = document.createElement("span");
      detailLabel.className = "startup-card-detail-label";
      detailLabel.textContent = year + " · Kurzprofil";

      const detailName = document.createElement("strong");
      detailName.className = "startup-card-detail-name";
      detailName.textContent = startup.name;

      const description = document.createElement("span");
      description.className = "startup-card-description";
      description.textContent = startup.description;

      const closeHint = document.createElement("span");
      closeHint.className = "startup-card-close-hint";
      closeHint.textContent = "Klick fixiert · Esc schließt";

      detail.append(detailLabel, detailName, description, closeHint);
      card.append(logoArea, footer, detail);
      item.append(card);
      fragment.append(item);

      card.addEventListener("click", () => {
        const willOpen = openCard !== card;
        closeOpenCard();
        if (willOpen) {
          card.classList.add("is-open");
          card.setAttribute("aria-expanded", "true");
          openCard = card;
        }
      });
    });

    grid.append(fragment);
  };

  const selectYear = (year, focusTab = false) => {
    if (!STARTUPS_BY_YEAR[year]) return;
    activeYear = year;

    yearList.querySelectorAll("[data-startup-year]").forEach((button) => {
      const selected = button.dataset.startupYear === year;
      button.classList.toggle("is-active", selected);
      button.setAttribute("aria-selected", String(selected));
      button.tabIndex = selected ? 0 : -1;
      if (selected) {
        grid.setAttribute("aria-labelledby", button.id);
        if (focusTab) button.focus();
      }
    });

    renderCards(year);
  };

  years.forEach((year, index) => {
    const button = document.createElement("button");
    button.className = "startup-year";
    button.type = "button";
    button.role = "tab";
    button.id = "startup-year-" + index;
    button.dataset.startupYear = year;
    button.textContent = year;
    button.setAttribute("aria-controls", "startup-gallery");
    button.addEventListener("click", () => selectYear(year));
    yearList.append(button);
  });

  yearList.addEventListener("keydown", (event) => {
    if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
    event.preventDefault();

    const currentIndex = years.indexOf(activeYear);
    let nextIndex = currentIndex;

    if (event.key === "ArrowLeft") nextIndex = (currentIndex - 1 + years.length) % years.length;
    if (event.key === "ArrowRight") nextIndex = (currentIndex + 1) % years.length;
    if (event.key === "Home") nextIndex = 0;
    if (event.key === "End") nextIndex = years.length - 1;

    selectYear(years[nextIndex], true);
  });

  archive.addEventListener("click", (event) => {
    if (event.target.closest(".startup-card")) return;
    closeOpenCard();
  });

  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape" || !openCard) return;
    const card = openCard;
    closeOpenCard();
    card.focus();
  });

  selectYear(activeYear);
})();
